请对以下 case 进行三维加权评分。

=== case_id ===
Case-12-finance-006

=== 用户原始指令 (query.txt) ===
给我整一行数字显示余额点一下进系统操作快没钱了提醒我

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "给我整一行数字显示余额点一下进系统操作快没钱了提醒我",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToIntent",
      "args": {
        "intentName": "ViewCalendarEvent",
        "params": {
          "entityId": "finance-ledger-entry"
        }
      }
    }
  ],
  "dataModelSchema": {
    "finance": {
      "accountName": {
        "type": "string",
        "description": "余额所属账户或记账钱包名称",
        "sampleValue": "账户余额"
      },
      "balanceDisplay": {
        "type": "string",
        "description": "当前余额的格式化金额展示文本",
        "sampleValue": "¥1,280"
      },
      "thresholdText": {
        "type": "string",
        "description": "余额提醒线的格式化展示文本",
        "sampleValue": "提醒线 ¥1,500"
      },
      "warningText": {
        "type": "string",
        "description": "低余额预警短状态",
        "sampleValue": "快没钱了"
      },
      "reminderText": {
        "type": "string",
        "description": "低余额提醒的处理建议",
        "sampleValue": "低于提醒线"
      },
      "actionLabel": {
        "type": "string",
        "description": "进入系统处理余额提醒的动作文案",
        "sampleValue": "去处理"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/bell_fill.svg",
      "description": "铃铛提醒图标，适合用于通知提醒、低余额预警或闹铃开启状态。"
    }
  ]
}

